<?php $this->assign('title', 'Solicitações de compra'); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Solicitações de compra</h1><p class="text-body-secondary">Cotação, aprovação e acompanhamento.</p></div><?= $this->Html->link('Nova solicitação', ['action' => 'add'], ['class' => 'btn btn-primary align-self-start']) ?></div><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Número</th><th>Solicitante</th><th>Status</th><th>Estimado</th><th>Data</th></tr></thead><tbody><?php foreach ($solicitacoes as $solicitacao): ?><tr><td><?= $this->Html->link($solicitacao->numero, ['action' => 'view', $solicitacao->id]) ?></td><td><?= h($solicitacao->solicitante->nome ?? '-') ?></td><td><span class="badge text-bg-secondary"><?= h(str_replace('_', ' ', $solicitacao->status)) ?></span></td><td>R$ <?= number_format((float)$solicitacao->valor_estimado, 2, ',', '.') ?></td><td><?= h($solicitacao->created->format('d/m/Y H:i')) ?></td></tr><?php endforeach; ?></tbody></table></div>
